  function addGrade3HistoryImages(lessonKey, filenames, topic){
    const lesson = window.K12_CLASSIC_25_DATA[lessonKey];
    if(!lesson || !Array.isArray(lesson.questions)) return;
    filenames.forEach((filename, questionIndex) => {
      const question = lesson.questions[questionIndex];
      if(!question) return;
      question.image = {
        src: `components/${filename}`,
        alt: `${topic} illustration for: ${question.q}`
      };
    });
  }

